/* sysinfo_example.c: Demonstrates the sysinfo(2) system call */
#include <stdio.h>
#include <stdlib.h>
#include <sys/sysinfo.h>
#include <errno.h>

#define LOAD_SCALE (1 << 16)

int main() {
    struct sysinfo info;
    // In older kernels, memory fields are always in bytes. 
    // Newer kernels may use mem_unit for scaling, but we assume byte size conversion here.
    long total_mem_mb, free_mem_mb;

    if (sysinfo(&info) != 0) {
        perror("sysinfo call failed");
        return EXIT_FAILURE;
    }

    // Convert memory sizes from bytes to Megabytes for readability
    // Note: If running on a modern system, check if info.mem_unit is necessary for accurate sizing.
    total_mem_mb = (info.totalram) / (1024 * 1024);
    free_mem_mb = (info.freeram) / (1024 * 1024);

    printf("--- System Information ---\n");
    printf("System Uptime: %ld seconds\n", info.uptime);
    printf("Total Processes: %u\n", info.procs);
    printf("Total RAM: %ld MB\n", total_mem_mb);
    printf("Free RAM: %ld MB\n", free_mem_mb);

    // Displaying load averages (must divide by 2^16)
    printf("Load Averages (1, 5, 15 min):\n");
    printf("  1 min: %.2f\n", (double)info.loads[0] / LOAD_SCALE);
    printf("  5 min: %.2f\n", (double)info.loads[1] / LOAD_SCALE);
    printf("  15 min: %.2f\n", (double)info.loads[2] / LOAD_SCALE);

    return EXIT_SUCCESS;
}
